func Start(ctx context.Context, js jetstream.JetStream, config Config) (*Runtime, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	config = config.withDefaults()
	if err := config.validate(); err != nil {
		return nil, err
	}
	if config.ClockCheck != nil && config.ClockCheck() != nil {
		return nil, ErrClockUnhealthy
	}
	logger := config.Logger
	if logger == nil {
		logger = slog.Default()
	}
	stream, err := openControlStream(ctx, js, config.Replicas)
	if err != nil {
		return nil, fmt.Errorf("open authority control log: %w", err)
	}
	readCtx, readCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readStream, err := js.Stream(readCtx, ControlStreamName)
	readCancel()
	if err != nil {
		return nil, fmt.Errorf("open authority read handle: %w", err)
	}
	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readInfo, err := readStream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return nil, fmt.Errorf("inspect authority read handle: %w", err)
	}
	if err := verifyControlStreamConfig(readInfo.Config, config.Replicas); err != nil {
		return nil, fmt.Errorf("validate authority read handle: %w", err)
	}
	loopCtx, cancel := context.WithCancel(ctx)
	runtime := &Runtime{
		js:          js,
		publisher:   js,
		stream:      stream,
		readStream:  readStream,
		config:      config,
		leaseSub:    fmt.Sprintf("%s.%s.lease", controlSubjectRoot, config.Scope),
		ownerID:     entityid.New(),
		logger:      logger,
		diagnostics: authorityDiagnosticQueue,
		diagTimes:   make(map[string]time.Time),
		cancel:      cancel,
		done:        make(chan struct{}),
	}
	runtime.publishSnapshot(Snapshot{Scope: config.Scope, DeploymentID: config.DeploymentID, CandidateID: config.CandidateID, OwnerID: runtime.ownerID, Reason: "not-observed"})
	runtime.logSnapshotTransition()
	var observeErr error
	for attempt := range startupReconcileAttempts {
		observeErr = runtime.reconcileWithRetry(loopCtx)
		runtime.logSnapshotTransition()
		if observeErr != nil && loopCtx.Err() != nil {
			observeErr = loopCtx.Err()
			break
		}
		if observeErr == nil || !retryableStartupReconcileError(loopCtx, observeErr) || attempt+1 == startupReconcileAttempts {
			break
		}
		timer := time.NewTimer(startupReconcileDelay(attempt, observeErr))
		select {
		case <-loopCtx.Done():
			observeErr = loopCtx.Err()
			timer.Stop()
		case <-timer.C:
		}
	}
	if observeErr != nil {
		cancel()
		close(runtime.done)
		return nil, fmt.Errorf("observe authority lease: %w", observeErr)
	}
	go runtime.run(loopCtx)
	return runtime, nil
}

func (r *Runtime) reconcile(ctx context.Context) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	info, err := r.stream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return stageFailure("stream_info", err)
	}
	if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
		return stageFailure("stream_config", err)
	}
	entryCtx, entryCancel := context.WithTimeout(ctx, authorityAPITimeout)
	entry, err := r.stream.GetLastMsgForSubject(entryCtx, r.leaseSub)
	entryCancel()
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return r.acquire(ctx, info.State.LastSeq, 0, 1)
	}
	if err != nil {
		return stageFailure("lease_msg_get", err)
	}
	if entry.Sequence > info.State.LastSeq {
		return stageFailure("lease_sequence_check", ErrConflict)
	}
	lease, err := decodeLease(entry.Data)
	if err != nil || lease.Scope != r.config.Scope || lease.Epoch == 0 {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Revision: entry.Sequence, ObservedAt: time.Now(), Reason: "lease-corrupt"})
		return nil
	}
	if lease.DeploymentID != r.config.DeploymentID {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID,
			CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Epoch: lease.Epoch,
			Revision: entry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
		return nil
	}
	expiresAt := entry.Time.Add(time.Duration(lease.LeaseDuration))
	now := time.Now()
	current := r.Current()
	if lease.IdentityResetSHA256 != "" {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID,
			CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Epoch: lease.Epoch,
			Revision: entry.Sequence, ObservedAt: now, Reason: "identity-reset-pending"})
		return nil
	}
	if !lease.Released && now.Before(expiresAt) {
		if lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID {
			r.publishSnapshot(Snapshot{
				Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Ready: true,
				Epoch: lease.Epoch, Revision: entry.Sequence, ExpiresAt: expiresAt,
				ObservedAt: now, Reason: "follower",
			})
			return nil
		}
		if current.Epoch != lease.Epoch || !current.Leader {
			return r.appendLease(ctx, info.State.LastSeq, entry.Sequence, lease.Epoch, false)
		}
		return r.appendLease(ctx, info.State.LastSeq, entry.Sequence, lease.Epoch, false)
	}
	if lease.CandidateID == r.config.CandidateID && lease.OwnerID == r.ownerID && current.Leader && current.Epoch == lease.Epoch {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Revision: entry.Sequence, ObservedAt: now, Reason: "lease-expired"})
	}
	return r.acquire(ctx, info.State.LastSeq, entry.Sequence, lease.Epoch+1)
}

func (r *Runtime) acquire(ctx context.Context, lastSequence, leaseSequence, epoch uint64) error {
	return r.appendLease(ctx, lastSequence, leaseSequence, epoch, false)
}

func (r *Runtime) appendLease(ctx context.Context, lastSequence, leaseSequence, epoch uint64, released bool) error {
	if epoch == 0 {
		return ErrFenced
	}
	if !released && r.checkClock() != nil {
		return ErrClockUnhealthy
	}
	lease := leaseRecord{
		Version: 1, Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID,
		Epoch: epoch, LeaseDuration: int64(r.config.LeaseDuration), TransitionID: entityid.New(), Released: released,
	}
	data, err := jsonMarshal(lease)
	if err != nil {
		return stageFailure("lease_encode", err)
	}
	msg := controlMessage(r.leaseSub, "lease", lease.TransitionID, data)
	publishCtx, publishCancel := context.WithTimeout(ctx, authorityAPITimeout)
	ack, err := r.publisher.PublishMsg(publishCtx, msg,
		jetstream.WithExpectLastSequence(lastSequence),
		jetstream.WithExpectLastSequenceForSubject(leaseSequence, r.leaseSub),
	)
	publishCancel()
	if err != nil {
		if isSequenceConflict(err) {
			return stageFailure("lease_publish", ErrConflict)
		}
		return stageFailure("lease_publish", r.resolveLeaseAppend(ctx, lease, err))
	}
	confirmCtx, confirmCancel := context.WithTimeout(ctx, authorityAPITimeout)
	stored, err := r.stream.GetLastMsgForSubject(confirmCtx, r.leaseSub)
	confirmCancel()
	if err != nil {
		return stageFailure("lease_confirm_get", r.resolveLeaseAppend(ctx, lease, err))
	}
	if stored.Sequence != ack.Sequence {
		return stageFailure("lease_confirm_sequence", ErrConflict)
	}
	confirmed, err := decodeLease(stored.Data)
	if err != nil || confirmed.Scope != r.config.Scope || confirmed.DeploymentID != r.config.DeploymentID || confirmed.CandidateID != r.config.CandidateID || confirmed.OwnerID != r.ownerID || confirmed.Epoch != epoch || confirmed.TransitionID != lease.TransitionID || confirmed.Released != released {
		return stageFailure("lease_confirm_record", ErrFenced)
	}
	if released {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Epoch: epoch, Revision: ack.Sequence, ObservedAt: time.Now(), Reason: "released"})
		return nil
	}
	now := time.Now()
	expiresAt := stored.Time.Add(time.Duration(confirmed.LeaseDuration))
	if !now.Before(expiresAt) {
		return stageFailure("lease_confirm_expiry", ErrFenced)
	}
	r.publishSnapshot(Snapshot{
		Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Leader: true, Ready: true,
		Epoch: epoch, Revision: ack.Sequence, ExpiresAt: expiresAt, ObservedAt: now, Reason: "leader",
	})
	return nil
}

func (r *Runtime) Guard(ctx context.Context, expectedEpoch uint64) error {
	if r == nil {
		return ErrNotLeader
	}
	if guard, ok := ctx.Value(verificationGuardKey{}).(*verificationGuard); ok {
		return r.guardVerification(ctx, expectedEpoch, guard)
	}
	if r.checkClock() != nil {
		return ErrClockUnhealthy
	}
	r.mu.Lock()
	current := r.Current()
	if !current.CanMutate() || current.Scope != r.config.Scope || current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		wasLocalLeader := current.Leader && current.CandidateID == r.config.CandidateID && current.OwnerID == r.ownerID
		r.mu.Unlock()
		r.logSnapshotTransition()
		if wasLocalLeader {
			r.recordFailure(stageFailure("guard_precondition", ErrNotLeader))
		}
		return ErrNotLeader
	}
	if expectedEpoch == 0 || current.Epoch != expectedEpoch {
		r.mu.Unlock()
		return ErrFenced
	}
	var lastErr error
	for range 8 {
		err := r.guardLocked(ctx, expectedEpoch)
		if !errors.Is(err, ErrConflict) {
			r.mu.Unlock()
			r.logSnapshotTransition()
			if err != nil {
				r.recordFailure(err)
			}
			return err
		}
		lastErr = err
	}
	if lastErr == nil {
		lastErr = stageFailure("guard_retry", ErrConflict)
	}
	r.mu.Unlock()
	r.logSnapshotTransition()
	r.recordFailure(lastErr)
	return lastErr
}

func (r *Runtime) guardLocked(ctx context.Context, expectedEpoch uint64) error {
	info, err := r.stream.Info(ctx)
	if err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "control-log-unavailable"})
		return stageFailure("guard_stream_info", err)
	}
	if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "control-log-incompatible"})
		return stageFailure("guard_stream_config", err)
	}
	entry, err := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
	if err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "lease-unreadable"})
		return stageFailure("guard_lease_msg_get", err)
	}
	if entry.Sequence > info.State.LastSeq {
		return stageFailure("guard_sequence_check", ErrConflict)
	}
	lease, err := decodeLease(entry.Data)
	if err != nil {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, OwnerID: r.ownerID, Reason: "lease-corrupt"})
		return stageFailure("guard_lease_decode", ErrLeaseCorrupt)
	}
	if lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID || lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID || lease.Epoch != expectedEpoch || lease.Released || !time.Now().Before(entry.Time.Add(time.Duration(lease.LeaseDuration))) {
		r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID, CandidateID: lease.CandidateID, OwnerID: lease.OwnerID, Epoch: lease.Epoch, Revision: entry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
		return stageFailure("guard_lease_check", ErrFenced)
	}
	return r.appendLease(ctx, info.State.LastSeq, entry.Sequence, expectedEpoch, false)
}

// Close stops renewal and, when possible, appends a release barrier. If NATS
// is unavailable the durable lease simply expires and the next candidate
// advances the epoch.
func (r *Runtime) Close() error {
	if r == nil {
		return nil
	}
	var closeErr error
	r.once.Do(func() {
		r.cancel()
		<-r.done
		current := r.Current()
		if current.CanMutate() && current.Scope == r.config.Scope && current.DeploymentID == r.config.DeploymentID && current.CandidateID == r.config.CandidateID && current.OwnerID == r.ownerID {
			ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
			defer cancel()
			r.mu.Lock()
			defer r.mu.Unlock()
			info, err := r.stream.Info(ctx)
			if err == nil && verifyControlStreamConfig(info.Config, r.config.Replicas) == nil {
				entry, getErr := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
				if getErr == nil {
					lease, decodeErr := decodeLease(entry.Data)
					if decodeErr == nil && lease.Scope == r.config.Scope && lease.DeploymentID == r.config.DeploymentID && lease.CandidateID == r.config.CandidateID && lease.OwnerID == r.ownerID && lease.Epoch == current.Epoch && !lease.Released {
						closeErr = r.appendLease(ctx, info.State.LastSeq, entry.Sequence, current.Epoch, true)
					}
				}
			}
		}
	})
	r.logSnapshotTransition()
	return closeErr
}

authority_log.text:
func (r *Runtime) CommitHostMutation(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
) (uint64, error) {
	if kind == MutationUsageObservation {
		return 0, errors.New("usage observations require verified host authority")
	}
	if err := validateHostMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	return r.commitMutation(ctx, expectedEpoch, kind, subjectKey, operationID, expectedSubjectSequence, payload)
}

func (r *Runtime) CommitHostMutationVerified(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	if err := validateHostMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	if verify == nil {
		return 0, errors.New("verified host mutation requires a verifier")
	}
	return r.commitMutationVerified(ctx, expectedEpoch, kind, subjectKey, operationID,
		expectedSubjectSequence, payload, verify)
}

func (r *Runtime) commitMutation(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
) (uint64, error) {
	return r.commitMutationVerified(ctx, expectedEpoch, kind, subjectKey, operationID,
		expectedSubjectSequence, payload, nil)
}

func (r *Runtime) commitMutationVerified(
	ctx context.Context,
	expectedEpoch uint64,
	kind HostMutationKind,
	subjectKey string,
	operationID string,
	expectedSubjectSequence uint64,
	payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	if r == nil {
		return 0, ErrNotLeader
	}
	if r.checkClock() != nil {
		return 0, ErrClockUnhealthy
	}
	if err := validateMutation(kind, subjectKey, operationID, payload); err != nil {
		return 0, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	current := r.Current()
	if !current.CanMutate() || current.Scope != r.config.Scope || current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		return 0, ErrNotLeader
	}
	if expectedEpoch == 0 || current.Epoch != expectedEpoch {
		return 0, ErrFenced
	}

	subject := mutationSubject(r.config.Scope, kind, subjectKey)
	for range 8 {
		info, err := r.stream.Info(ctx)
		if err != nil {
			return 0, fmt.Errorf("read control log sequence: %w", err)
		}
		if err := verifyControlStreamConfig(info.Config, r.config.Replicas); err != nil {
			return 0, fmt.Errorf("validate control log consistency: %w", err)
		}
		leaseEntry, err := r.stream.GetLastMsgForSubject(ctx, r.leaseSub)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-unreadable"})
			return 0, err
		}
		if leaseEntry.Sequence > info.State.LastSeq {
			continue
		}
		lease, err := decodeLease(leaseEntry.Data)
		if err != nil {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: r.config.DeploymentID, CandidateID: r.config.CandidateID, Reason: "lease-corrupt"})
			return 0, ErrLeaseCorrupt
		}
		if lease.Scope != r.config.Scope || lease.DeploymentID != r.config.DeploymentID || lease.CandidateID != r.config.CandidateID || lease.OwnerID != r.ownerID || lease.Epoch != expectedEpoch || lease.Released ||
			!time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
			r.publishSnapshot(Snapshot{Scope: r.config.Scope, DeploymentID: lease.DeploymentID, CandidateID: lease.CandidateID, Epoch: lease.Epoch, Revision: leaseEntry.Sequence, ObservedAt: time.Now(), Reason: "lease-fenced"})
			return 0, ErrFenced
		}

		existing, err := r.stream.GetLastMsgForSubject(ctx, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			existing = nil
		} else if err != nil {
			return 0, fmt.Errorf("read prior host mutation: %w", err)
		}
		if existing != nil && existing.Sequence > info.State.LastSeq {
			continue
		}
		if existing != nil {
			prior, decodeErr := decodeControlRecord(existing.Data)
			if decodeErr != nil {
				return 0, fmt.Errorf("decode prior host mutation: %w", decodeErr)
			}
			if prior.OperationID == operationID {
				if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
					return existing.Sequence, nil
				}
				return 0, ErrOperationConflict
			}
			if existing.Sequence != expectedSubjectSequence {
				return 0, ErrConflict
			}
		} else if expectedSubjectSequence != 0 {
			return 0, ErrConflict
		}
		if verify != nil {
			if err := r.verify(ctx, expectedEpoch, leaseEntry.Sequence, info.State.LastSeq,
				subject, operationID, leaseEntry.Time.Add(time.Duration(lease.LeaseDuration)), verify); err != nil {
				return 0, err
			}
			if !time.Now().Before(leaseEntry.Time.Add(time.Duration(lease.LeaseDuration))) {
				return 0, ErrFenced
			}
		}

		record := controlRecord{
			Version: 1, Kind: kind, Scope: r.config.Scope, SubjectKey: subjectKey,
			OperationID: operationID, Epoch: expectedEpoch, Payload: bytes.Clone(payload),
		}
		data, err := json.Marshal(record)
		if err != nil {
			return 0, err
		}
		msg := controlMessage(subject, string(kind), operationID, data)
		ack, err := r.js.PublishMsg(ctx, msg,
			jetstream.WithExpectLastSequence(info.State.LastSeq),
			jetstream.WithExpectLastSequenceForSubject(expectedSubjectSequence, subject),
		)
		if err == nil {
			return ack.Sequence, nil
		}
		if isSequenceConflict(err) {
			latest, readErr := r.stream.GetLastMsgForSubject(ctx, subject)
			if readErr == nil {
				prior, decodeErr := decodeControlRecord(latest.Data)
				if decodeErr == nil && prior.OperationID == operationID {
					if prior.Kind == kind && prior.SubjectKey == subjectKey && prior.Epoch == expectedEpoch && bytes.Equal(prior.Payload, payload) {
						return latest.Sequence, nil
					}
					return 0, ErrOperationConflict
				}
				if latest.Sequence != expectedSubjectSequence {
					return 0, ErrConflict
				}
			}
			continue
		}
		return r.resolveUnknownMutation(ctx, subject, kind, subjectKey, operationID, expectedEpoch, payload, err)
	}
	return 0, ErrConflict
}

// ReadHostMutation reads the current committed host record.
func (r *Runtime) ReadHostMutation(ctx context.Context, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	if r == nil {
		return LogEntry{}, ErrNotFound
	}
	if err := validateMutationKey(kind, subjectKey); err != nil {
		return LogEntry{}, err
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	return readMutation(ctx, r.readStream, r.config.Scope, kind, subjectKey)
}

func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil
}

func (r *Runtime) BeginActiveWorkloadEffect(ctx context.Context, epoch uint64, scope WorkloadScope) (func(), error) {
	if ctx != nil {
		if state, ok := ctx.Value(workloadEffectContextKey{}).(*workloadEffectContext); ok {
			state.mu.Lock()
			if held := state.active[scope]; held != nil {
				if held.runtime != r || held.epoch != epoch {
					state.mu.Unlock()
					return nil, ErrFenced
				}
				held.refs++
				state.mu.Unlock()
				release := sync.OnceFunc(func() { state.release(scope) })
				if err := r.Guard(ctx, epoch); err != nil {
					release()
					return nil, err
				}
				return release, nil
			}
			gate := r.workloadGate(scope)
			gate.RLock()
			if err := r.requireNoTerminalIntent(ctx, scope.DatabaseID, scope.PartitionID); err != nil {
				gate.RUnlock()
				state.mu.Unlock()
				return nil, err
			}
			if err := r.Guard(ctx, epoch); err != nil {
				gate.RUnlock()
				state.mu.Unlock()
				return nil, err
			}
			state.active[scope] = &heldWorkloadEffect{runtime: r, epoch: epoch, gate: gate, refs: 1}
			state.mu.Unlock()
			return sync.OnceFunc(func() { state.release(scope) }), nil
		}
	}
	release, err := r.beginWorkloadGate(ctx, scope)
	if err != nil {
		return nil, err
	}
	if err := r.requireNoTerminalIntent(ctx, scope.DatabaseID, scope.PartitionID); err != nil {
		release()
		return nil, err
	}
	if err := r.Guard(ctx, epoch); err != nil {
		release()
		return nil, err
	}
	return release, nil
}

func openControlStream(ctx context.Context, js jetstream.JetStream, replicas int) (jetstream.Stream, error) {
	config := jetstream.StreamConfig{
		Name:              ControlStreamName,
		Description:       "Fenced regional authority, operation, and host mutation log",
		Subjects:          []string{controlStreamSubject},
		Retention:         jetstream.LimitsPolicy,
		MaxConsumers:      -1,
		MaxMsgs:           -1,
		MaxBytes:          -1,
		MaxMsgsPerSubject: -1,
		Storage:           jetstream.FileStorage,
		Replicas:          replicas,
		DenyDelete:        true,
		DenyPurge:         true,
		// Lease reads must go through the stream leader; direct reads can be stale on followers.
		AllowDirect: false,
		Metadata:    map[string]string{"terrascale-contract": "authority-log-v1"},
	}
	// JetStream only applies its default API timeout when the caller has no
	// deadline. A long startup deadline must not let one lost reply consume the
	// entire attempt.
	createCtx, cancel := context.WithTimeout(ctx, authorityAPITimeout)
	stream, err := js.CreateStream(createCtx, config)
	cancel()
	created := err == nil
	if err != nil {
		if !errors.Is(err, jetstream.ErrStreamNameAlreadyInUse) && !errors.Is(err, jetstream.ErrBucketExists) {
			return nil, fmt.Errorf("create authority stream: %w", err)
		}
		lookupCtx, lookupCancel := context.WithTimeout(ctx, authorityAPITimeout)
		stream, err = js.Stream(lookupCtx, ControlStreamName)
		lookupCancel()
		if err != nil {
			return nil, fmt.Errorf("lookup existing authority stream: %w", err)
		}
	}
	var info *jetstream.StreamInfo
	if created {
		info, err = inspectCreatedControlStream(ctx, stream, createdStreamInfoConvergenceWindow)
	} else {
		infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
		info, err = stream.Info(infoCtx)
		infoCancel()
	}
	if err != nil {
		return nil, fmt.Errorf("inspect authority stream: %w", err)
	}
	if info == nil {
		return nil, errors.New("authority stream info is missing")
	}
	if err := verifyControlStreamConfig(info.Config, replicas); err != nil {
		return nil, err
	}
	return stream, nil
}

// A new R3 stream may be visible to CreateStream before its metadata leader
// serves Info. Retry only the exact stream-not-found API response at this one
// post-create boundary, within both the caller deadline and a short local cap.
func inspectCreatedControlStream(ctx context.Context, stream jetstream.Stream,
	convergenceWindow time.Duration,
) (*jetstream.StreamInfo, error) {
	windowCtx, cancel := context.WithTimeout(ctx, convergenceWindow)
	defer cancel()
	for {
		infoCtx, infoCancel := context.WithTimeout(windowCtx, authorityAPITimeout)
		info, err := stream.Info(infoCtx)
		infoCancel()
		if err == nil {
			return info, nil
		}
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		apiErr, ok := errors.AsType[*jetstream.APIError](err)
		if !ok || apiErr.Code != 404 || apiErr.ErrorCode != jetstream.JSErrCodeStreamNotFound {
			return nil, err
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-windowCtx.Done():
			return nil, err
		case <-time.After(createdStreamInfoRetryDelay):
		}
	}
}

func verifyControlStreamConfig(actual jetstream.StreamConfig, replicas int) error {
	if (replicas != 1 && replicas != 3 && replicas != 5) || actual.Name != ControlStreamName ||
		actual.Replicas != replicas || actual.Retention != jetstream.LimitsPolicy ||
		actual.Storage != jetstream.FileStorage || actual.MaxConsumers != -1 ||
		actual.MaxMsgs != -1 || actual.MaxBytes != -1 ||
		actual.MaxMsgsPerSubject != -1 || actual.MaxAge != 0 || actual.Discard != jetstream.DiscardOld ||
		actual.MaxMsgSize > 0 || actual.DiscardNewPerSubject || actual.AllowRollup ||
		actual.AllowDirect || actual.MirrorDirect || actual.NoAck || actual.Sealed ||
		!actual.DenyDelete || !actual.DenyPurge || len(actual.Subjects) != 1 ||
		actual.Subjects[0] != controlStreamSubject || actual.Mirror != nil || len(actual.Sources) != 0 ||
		actual.SubjectTransform != nil || actual.RePublish != nil || actual.AllowMsgTTL ||
		actual.SubjectDeleteMarkerTTL != 0 || actual.AllowMsgSchedules ||
		actual.Metadata["terrascale-contract"] != "authority-log-v1" {
		return errors.New("existing control log has incompatible consistency, durability, or subject configuration")
	}
	return nil
}

